'use strict';

// MODULES //

var dtypes = require( '@stdlib/ndarray/dtypes' );
var gindexOfFalsy = require( '@stdlib/blas/ext/base/ndarray/gindex-of-falsy' );
var dindexOfFalsy = require( '@stdlib/blas/ext/base/ndarray/dindex-of-falsy' );
var sindexOfFalsy = require( '@stdlib/blas/ext/base/ndarray/sindex-of-falsy' );
var zindexOfFalsy = require( '@stdlib/blas/ext/base/ndarray/zindex-of-falsy' );
var cindexOfFalsy = require( '@stdlib/blas/ext/base/ndarray/cindex-of-falsy' );
var factory = require( '@stdlib/ndarray/base/unary-reduce-strided1d-dispatch-factory' );


// VARIABLES //

var idtypes0 = dtypes( 'all' ); // input ndarray
var idtypes1 = dtypes( 'integer_index_and_generic' ); // from index ndarray
var odtypes = dtypes( 'integer_index_and_generic' );
var policies = {
	'output': 'integer_index_and_generic',
	'casting': 'none'
};
var table = {
	'types': [
		'float64',
		'float32',
		'complex128',
		'complex64'
	],
	'fcns': [
		dindexOfFalsy,
		sindexOfFalsy,
		zindexOfFalsy,
		cindexOfFalsy
	],
	'default': gindexOfFalsy
};


// MAIN //

/**
* Returns the index of the first falsy element along an ndarray dimension.
*
* ## Notes
*
* -   If unable to find a falsy element along an ndarray dimension, the corresponding element in the returned ndarray is `-1`.
* -   The function explicitly treats `NaN` values as falsy.
*
* @private
* @name indexOfFalsy
* @type {Function}
* @param {ndarrayLike} x - input ndarray
* @param {ndarrayLike} fromIndex - indices from which to begin searching
* @param {Options} [options] - function options
* @param {IntegerArray} [options.dims] - list of dimensions over which to perform operation
* @param {*} [options.dtype] - output ndarray data type
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} second argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {RangeError} dimension indices must not exceed input ndarray bounds
* @throws {RangeError} number of dimension indices must not exceed the number of input ndarray dimensions
* @throws {Error} must provide valid options
* @returns {ndarray} output ndarray
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/ctor' );
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ 1.0, 3.0, 0.0, 2.0, 0.0, 4.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 6 ];
*
* // Define the array strides:
* var sx = [ 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Create a from index ndarray:
* var fromIndex = scalar2ndarray( 0, {
*     'dtype': 'int32'
* });
*
* // Perform operation:
* var out = indexOfFalsy( x, fromIndex );
* // returns <ndarray>[ 2 ]
*/
var indexOfFalsy = factory( table, [ idtypes0, idtypes1 ], odtypes, policies );


// EXPORTS //

module.exports = indexOfFalsy;

// exports: { "assign": "indexOfFalsy.assign" }
